(function(){
  "use strict";

  // ---------- the official poster, embedded ----------
  const POSTER_SRC = "data:image/jpeg;base64,";

  // screen (monitor) rect within the 1024x1037 poster, in source px
  const SCREEN = { x:305, y:188, w:449, h:556 };
  // nameplate text-safe rect within the poster, in source px
  const PLAQUE = { x:398, y:923, w:282, h:66 };

  const poster = new Image();
  let posterReady = false;
  poster.onload = ()=>{ posterReady = true; drawUpload(); };
  poster.src = POSTER_SRC;

  // ---------- state ----------
  const state = { imgEl:null, name:"", role:"", title:"" };

  const TITLES = [
    "Midnight Shipper","Terminal Whisperer","Fiber-Optic Nomad","Sunset Committer",
    "Ocean-Side Debugger","Zero-to-One Builder","Sandbox Architect","Coconut-Fueled Coder",
    "Tide-Table Hacker","Merge Conflict Survivor","Night Owl Deployer","Prototype Pirate",
    "Full-Stack Castaway","API Alchemist","Golden Hour Engineer","Beachside Bug Slayer",
    "Stack Overflow Surfer","Late-Night Launcher","Idea-to-Prod Sprinter","Chaos Coordinator",
    "Signal Chaser","Build Station Regular"
  ];
  function randomTitle(){ return TITLES[Math.floor(Math.random()*TITLES.length)]; }

  // ---------- step nav ----------
  const steps = [null, document.getElementById('step1'), document.getElementById('step2'), document.getElementById('step3')];
  const dots = document.querySelectorAll('#dots span');
  function goTo(n){
    for(let i=1;i<=3;i++){ steps[i].classList.toggle('active', i===n); }
    dots.forEach(d=>{
      const s = +d.dataset.step;
      d.classList.toggle('active', s===n);
      d.classList.toggle('done', s<n);
    });
    if(n===3) drawResult();
    window.scrollTo({top:0, behavior:'smooth'});
  }

  // ---------- toast ----------
  const toastEl = document.getElementById('toast');
  let toastTimer;
  function toast(msg){
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>toastEl.classList.remove('show'), 2200);
  }

  function roundRect(c,x,y,w,h,r){
    c.beginPath();
    c.moveTo(x+r,y);
    c.arcTo(x+w,y,x+w,y+h,r);
    c.arcTo(x+w,y+h,x,y+h,r);
    c.arcTo(x,y+h,x,y,r);
    c.arcTo(x,y,x+w,y,r);
    c.closePath();
  }

  function fitFont(c, text, maxW, baseSize, weight, family){
    let size = baseSize;
    c.font = `${weight} ${size}px '${family}'`;
    while(c.measureText(text).width > maxW && size > 11){
      size -= 1;
      c.font = `${weight} ${size}px '${family}'`;
    }
    return size;
  }

  // draws the photo (cover-fit) into the monitor screen rect of a given canvas ctx
  function drawPhotoIntoScreen(c){
    if(!state.imgEl) return;
    c.save();
    c.beginPath();
    c.rect(SCREEN.x, SCREEN.y, SCREEN.w, SCREEN.h);
    c.clip();
    const img = state.imgEl;
    const scale = Math.max(SCREEN.w/img.width, SCREEN.h/img.height);
    const dw = img.width*scale, dh = img.height*scale;
    const dx = SCREEN.x + (SCREEN.w-dw)/2;
    const dy = SCREEN.y + (SCREEN.h-dh)/2;
    c.drawImage(img, dx, dy, dw, dh);
    c.restore();
  }

  // ---------- step 1: upload canvas ----------
  const uploadCanvas = document.getElementById('uploadCanvas');
  const uCtx = uploadCanvas.getContext('2d');
  const posterCard = document.getElementById('posterCard');
  const fileInput = document.getElementById('fileInput');
  const changePhotoBtn = document.getElementById('changePhotoBtn');
  const toStep2Btn = document.getElementById('toStep2');

  function drawUpload(){
    if(!posterReady) return;
    uCtx.clearRect(0,0,uploadCanvas.width, uploadCanvas.height);
    uCtx.drawImage(poster, 0, 0, uploadCanvas.width, uploadCanvas.height);
    if(state.imgEl){
      drawPhotoIntoScreen(uCtx);
    }
  }

  posterCard.addEventListener('click', (e)=>{
    if(e.target === changePhotoBtn) return;
    fileInput.click();
  });
  changePhotoBtn.addEventListener('click', (e)=>{ e.stopPropagation(); fileInput.click(); });

  ['dragover','dragenter'].forEach(evt=>{
    posterCard.addEventListener(evt, e=>{ e.preventDefault(); posterCard.classList.add('drag-over'); });
  });
  ['dragleave','dragend','drop'].forEach(evt=>{
    posterCard.addEventListener(evt, e=>{ posterCard.classList.remove('drag-over'); });
  });
  posterCard.addEventListener('drop', e=>{
    e.preventDefault();
    const f = e.dataTransfer.files && e.dataTransfer.files[0];
    if(f) handleFile(f);
  });
  fileInput.addEventListener('change', e=>{
    const f = e.target.files && e.target.files[0];
    if(f) handleFile(f);
  });

  function handleFile(file){
    if(!file.type.startsWith('image/')){ toast('Please choose an image file'); return; }
    const reader = new FileReader();
    reader.onload = (ev)=>{
      const img = new Image();
      img.onload = ()=>{
        state.imgEl = img;
        drawUpload();
        changePhotoBtn.style.display = 'block';
        toStep2Btn.disabled = false;
        toast('Photo added ✓');
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  }

  toStep2Btn.addEventListener('click', ()=>{ if(state.imgEl) goTo(2); });

  // ---------- step 2: details ----------
  const nameInput = document.getElementById('nameInput');
  const roleInput = document.getElementById('roleInput');
  const titleInput = document.getElementById('titleInput');
  const diceBtn = document.getElementById('diceBtn');
  const nameHint = document.getElementById('nameHint');

  titleInput.value = randomTitle();
  diceBtn.addEventListener('click', ()=>{ titleInput.value = randomTitle(); });

  document.getElementById('toStep1').addEventListener('click', ()=>goTo(1));
  document.getElementById('toStep2b').addEventListener('click', ()=>goTo(2));

  document.getElementById('toStep3').addEventListener('click', ()=>{
    const name = nameInput.value.trim();
    if(!name){
      nameInput.classList.add('err');
      nameHint.classList.add('show');
      nameInput.focus();
      return;
    }
    nameInput.classList.remove('err');
    nameHint.classList.remove('show');
    state.name = name;
    state.role = roleInput.value.trim() || "Builder";
    state.title = titleInput.value.trim() || randomTitle();
    goTo(3);
  });
  nameInput.addEventListener('input', ()=>{
    if(nameInput.value.trim()){ nameInput.classList.remove('err'); nameHint.classList.remove('show'); }
  });

  document.getElementById('startOverBtn').addEventListener('click', ()=>{
    state.imgEl = null;
    changePhotoBtn.style.display='none';
    toStep2Btn.disabled = true;
    fileInput.value = '';
    nameInput.value=''; roleInput.value=''; titleInput.value=randomTitle();
    drawUpload();
    goTo(1);
  });

  // ---------- step 3: final card ----------
  const resultCanvas = document.getElementById('resultCanvas');
  const rCtx = resultCanvas.getContext('2d');

  function drawResult(){
    if(!posterReady) return;
    rCtx.clearRect(0,0,resultCanvas.width, resultCanvas.height);
    rCtx.drawImage(poster, 0, 0, resultCanvas.width, resultCanvas.height);
    drawPhotoIntoScreen(rCtx);

    // ---- nameplate overlay ----
    const { x, y, w, h } = PLAQUE;
    roundRect(rCtx, x, y, w, h, 4);
    const grad = rCtx.createLinearGradient(x, y, x, y+h);
    grad.addColorStop(0, '#5a4632');
    grad.addColorStop(0.45, '#c9a074');
    grad.addColorStop(0.55, '#b98f5f');
    grad.addColorStop(1, '#4a3626');
    rCtx.fillStyle = grad;
    rCtx.fill();
    rCtx.lineWidth = 1;
    rCtx.strokeStyle = 'rgba(20,12,4,.5)';
    rCtx.stroke();

    rCtx.textAlign = 'center';
    rCtx.fillStyle = '#241206';

    const nameText = state.name.toUpperCase();
    const nameSize = fitFont(rCtx, nameText, w-30, 25, 700, 'Space Grotesk');
    rCtx.font = `700 ${nameSize}px 'Space Grotesk'`;
    rCtx.fillText(nameText, x+w/2, y+h*0.44);

    const roleText = state.role;
    const roleSize = fitFont(rCtx, roleText, w-30, 15, 600, 'Inter');
    rCtx.font = `600 ${roleSize}px 'Inter'`;
    rCtx.fillStyle = '#3a2412';
    rCtx.fillText(roleText, x+w/2, y+h*0.8);

    // ---- builder title ribbon, bottom of frame ----
    const ribbonY = 1000;
    rCtx.font = "700 15px 'JetBrains Mono'";
    const titleText = ('★ ' + state.title.toUpperCase() + ' · #FRAMEINGOA').trim();
    const tw = rCtx.measureText(titleText).width + 36;
    roundRect(rCtx, resultCanvas.width/2 - tw/2, ribbonY, tw, 30, 15);
    rCtx.fillStyle = 'rgba(10,14,20,.72)';
    rCtx.fill();
    rCtx.lineWidth = 1;
    rCtx.strokeStyle = 'rgba(242,184,75,.65)';
    rCtx.stroke();
    rCtx.fillStyle = '#f2b84b';
    rCtx.fillText(titleText, resultCanvas.width/2, ribbonY+20);
  }

  // ---------- download / share ----------
  function canvasToBlob(){
    return new Promise(resolve=>resultCanvas.toBlob(resolve, 'image/png', 1));
  }
  function downloadBlob(blob){
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'hh-goa-2026-builder-id.png';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 4000);
  }

  document.getElementById('downloadBtn').addEventListener('click', async ()=>{
    const blob = await canvasToBlob();
    downloadBlob(blob);
    toast('Downloaded ✓');
  });

  document.getElementById('shareBtn').addEventListener('click', async ()=>{
    const blob = await canvasToBlob();
    const text = "I'm building at Hacker House Goa 2026 🌴⚡ Made my Builder ID with the HH Goa ID Card Generator. #FrameInGoa";
    const file = new File([blob], 'hh-goa-2026-builder-id.png', {type:'image/png'});

    if(navigator.canShare && navigator.canShare({files:[file]})){
      try{
        await navigator.share({files:[file], text, title:'HH Goa 2026 Builder ID'});
        return;
      }catch(err){
        if(err && err.name === 'AbortError') return;
      }
    }
    downloadBlob(blob);
    toast('Image downloaded — attach it on X');
    const tweet = 'https://twitter.com/intent/tweet?text=' + encodeURIComponent(text);
    setTimeout(()=>window.open(tweet, '_blank'), 600);
  });

})();
